// Ported from the Node app's Sequelize model Book (first generated by tools/gen-efcore.mjs).
using System.Text.Json.Nodes;
using System.Text.Json.Serialization;
using SchoolERP.Domain.Common;

namespace SchoolERP.Domain.Entities;

/// <summary>Table <c>books</c>.</summary>
public class Book : AuditableEntity
{
    public int Id { get; set; }
    public string Title { get; set; } = null!;
    public string? Author { get; set; }
    public int? CategoryId { get; set; }
    public string? Isbn { get; set; }
    public int Copies { get; set; } = 1;
    public int Available { get; set; } = 1;

    [JsonIgnore]
    public ICollection<BookIssue> BookIssues { get; set; } = new List<BookIssue>();
    [JsonPropertyName("LibraryCategory")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public LibraryCategory? LibraryCategory { get; set; }
    [JsonIgnore]
    public ICollection<BookReservation> BookReservations { get; set; } = new List<BookReservation>();
}
